{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "In healthy volunteers, cromolyn oral suspension had systemic bioavailability of about 1%, far below the 20% threshold; this direct human systemic-availability measurement transfers strongly to the query's phenolic chromone/coumarin-like scaffold and supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Bazedoxifene had an absolute oral bioavailability of 6% versus IV in healthy postmenopausal women, below 20%; the high transferability of this human absolute-F measurement supports low oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Trans-resveratrol in humans had oral bioavailability <1%, demonstrating that phenolic polyphenols undergo extensive presystemic metabolism/conjugation and very low systemic F; this pattern is relevant to the query's phenolic coumarin.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Naringenin oral bioavailability in healthy volunteers was 5.8%, below 20%, supporting low F for small phenolic compounds with similar conjugation liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Fenoterol has ~2% oral bioavailability in humans due to extensive presystemic sulfation by SULT enzymes; this mechanism is directly relevant to phenolic substrates such as the query and supports low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability well below 20% (approximately 1-6%), and the query's phenolic coumarin structure is expected to share the same presystemic conjugation and low systemic availability liabilities; therefore predict low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for 4-methylumbelliferone (hymecromone) is provided.",
    "Most evidence reports parent systemic availability; total conjugates may be higher, but the endpoint concerns parent F.",
    "The query is smaller and less polar than several analogues, so extrapolation carries some uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

